local function saveConfig()
	if not writefile then
		return
	end;
	pcall(function()
		local out = {
			equipped = {},
			favorites = favorites
		}
		for wpn, cos in pairs(equipped) do
			out.equipped[wpn] = {}
			for ct, cd in pairs(cos) do
				if cd and cd.Name then
					out.equipped[wpn][ct] = {
						name = cd.Name,
						seed = cd.Seed,
						inverted = cd.Inverted
					}
				end
			end
		end;
		if not isfolder("Singularity") then
			makefolder("Singularity")
		end;
		writefile("Singularity/skins.json", HttpService:JSONEncode(out))
	end)
end;
local function loadConfig()
	if not readfile or not isfile or not isfile("Singularity/skins.json") then
		return
	end;
	pcall(function()
		local cfg = HttpService:JSONDecode(readfile("Singularity/skins.json"))
		if cfg.equipped then
			for wpn, cos in pairs(cfg.equipped) do
				equipped[wpn] = {}
				for ct, cd in pairs(cos) do
					local base = CosmeticLibrary.Cosmetics and CosmeticLibrary.Cosmetics[cd.name]
					if base then
						local data = {}
						for k, v in pairs(base) do
							data[k] = v
						end;
						data.Name = cd.name;
						data.Seed = cd.seed;
						data.Inverted = cd.inverted;
						equipped[wpn][ct] = data
					end
				end
			end
		end;
		favorites = cfg.favorites or {}
	end)
end;
