local function patchItemLibrary()
	local orig = ItemLibrary.GetViewModelImageFromWeaponData;
	ItemLibrary.GetViewModelImageFromWeaponData = function(self, wd, highRes)
		if not wd then
			return orig(self, wd, highRes)
		end;
		local wn = wd.Name;
		if equipped[wn] and equipped[wn].Skin then
			local si = self.ViewModels[equipped[wn].Skin.Name]
			if si then
				return si[highRes and "ImageHighResolution" or "Image"] or si.Image
			end
		end;
		return orig(self, wd, highRes)
	end
end;
